from pathlib import Path
import json,re,html
ROOT=Path(__file__).resolve().parents[1];ASSETS=ROOT/'s6-figures';ASSETS.mkdir(exist_ok=True)
groups={}
def unit(name,rows):
 data=[]
 for line in rows.strip().splitlines():
  q,a,w1,w2,w3,h,e=line.split('|');wrongs=[w.split('~',1) for w in [w1,w2,w3]];assert len(wrongs)==3
  data.append((q,a,wrongs,h,e))
 assert len(data)==10,(name,len(data));groups[name]=data
