# Lever plots: equally spaced numbered marks and explicit individual masses.
def lever(name,weights,caption):
 cx,cy,step=330,140,43
 b='<path d="M65 140 H595" stroke="#47728a" stroke-width="9"/><path d="M330 145 L306 195 H354 Z" fill="#a9c5d6" stroke="#47728a" stroke-width="2"/>'+text(330,230,'支点')
 for i in range(-6,7):
  x=cx+i*step;b+=f'<path d="M{x} 126 V154" stroke="#2b5e78" stroke-width="2"/>'
  if i:b+=text(x,111,str(abs(i)),20)
 for index,mass in weights:
  x=cx+index*step;b+=f'<path d="M{x} 148 V280" stroke="#7d7f7c" stroke-width="2"/><rect x="{x-17}" y="280" width="34" height="52" rx="6" fill="#c6d7e3" stroke="#47728a" stroke-width="2"/>'+text(x,365,mass,22)
 return svg(name,b,caption+' 目盛りの間隔は左右同じです。図はつるす位置を示し、実際の傾きを表すものではありません。')
