def ruby(s):
 keys=sorted(READINGS,key=len,reverse=True);pattern=re.compile('|'.join(map(re.escape,keys)))
 return ''.join(part if part.startswith('{') else pattern.sub(lambda m:'{'+m[0]+'|'+READINGS[m[0]]+'}',part) for part in re.split(r'(\{[^{}]+\})',s))
for q in records:
 for k in ['question','answer','explanation']:q[k]=ruby(q[k])
 q['choices']=[ruby(s) for s in q['choices']];q['hints']=[ruby(s) for s in q['hints']];q['misconceptions']=[{'answer':ruby(x['answer']),'reason':ruby(x['reason'])} for x in q['misconceptions']]
 assert 1<=len(q['hints'])<=2
source='// 小6理科の新作100問。利用者レビュー待ち。\n(function(root){\n"use strict";\nroot.FF.units.DEFS.science[6]='+json.dumps(units,ensure_ascii=False,indent=2)+';\n(root.QUESTION_BANK||[]).forEach(function(q){if(q.subject===\'science\'&&q.gradeLevel===6){if(q.unit===\'gas\')q.unit=\'combustion\';if(q.id===\'science_g6_plant_001\')q.unit=\'plant_water\';}});\nvar questions='+json.dumps(records,ensure_ascii=False,indent=2)+';\nArray.prototype.push.apply(root.QUESTION_BANK=root.QUESTION_BANK||[],questions);\n})(this);\n'
(ROOT/'science-g6-course.js').write_text(source)
lines=['# 小学6年 理科 新作100問','','10分野各10問。基礎40・標準40・発展20。ヒント1〜2個と誤答3つの理由付き。利用者レビュー用。']
for q in records:
 lines+=['',f'## {q["id"]}（{NAMES[q["unit"]]}・{q["difficulty"]}）','',plain(q['question']),'','選択肢：'+' ／ '.join(map(plain,q['choices'])),'','正解：'+plain(q['answer']),'','ヒント：'+' ／ '.join(map(plain,q['hints'])),'',plain(q['explanation'])]
 if 'diagram'in q:lines+=['','図：'+json.dumps(q['diagram'],ensure_ascii=False)]
(ROOT/'S6_QUESTIONS_REVIEW.md').write_text('\n'.join(lines)+'\n')
print('questions',len(records),'diagrams',sum('diagram'in q for q in records))
